'use strict';

// Pure render helper: array of names -> <li> markup.
function renderList(names) {
  return names.map((name) => `<li>${name}</li>`).join('\n');
}

// Pure filter helper: names whose text contains query, case-insensitively.
function filterNames(names, query) {
  const needle = query.trim().toLowerCase();
  if (!needle) return names;
  return names.filter((name) => name.toLowerCase().includes(needle));
}

// Dual environment: browser (script tag, no module) + node tests (require).
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { renderList, filterNames };
}

